        .args(["data", "declarations", stage])
        .arg("--config")
        .arg(config)
        .arg("--ingestion-key")
        .arg(key.to_string())
        .env_remove("DATABASE_URL")
        .env("PATH", "/nonexistent")
        .output()
        .unwrap()
}
